// sum.js
function sum(a, b) {
  return a + b;
}
module.exports = sum;

// sum.test.js
const sum = require('./sum');

describe('sum', () => {
  it('두 수를 더한 값을 반환한다', () => {
    expect(sum(1, 2)).toBe(3);
  });

  it('음수도 정상적으로 더한다', () => {
    expect(sum(-1, -2)).toBe(-3);
  });
});
